import type { Redis } from "ioredis";

export class RateLimiter {
  private hits = new Map<string, number[]>();

  constructor(private redis: Redis | null, private limit: number, private windowMs: number) {}

  async take(key: string): Promise<boolean> {
    if (!this.redis) return this.takeLocal(key);
    const now = Date.now();
    const k = `rl:${key}`;
    await this.redis.zremrangebyscore(k, 0, now - this.windowMs);
    const count = await this.redis.zcard(k);
    if (count >= this.limit) return false;
    await this.redis.zadd(k, now, `${now}-${Math.random()}`);
    await this.redis.pexpire(k, this.windowMs);
    return true;
  }

  async reset() {
    const keys = await this.redis!.keys("rl:*");
    if (keys.length) await this.redis!.del(...keys);
  }

  private takeLocal(key: string) {
    const now = Date.now();
    const arr = (this.hits.get(key) ?? []).filter((t) => t > now - this.windowMs);
    if (arr.length >= this.limit) return false;
    arr.push(now);
    this.hits.set(key, arr);
    return true;
  }
}

