describe('formatDueDate', () => {
  afterEach(() => {
    vi.unstubAllEnvs();
    vi.resetModules();
  });

  it('formats in the viewer timezone, not UTC', async () => {
    vi.stubEnv('TZ', 'America/Vancouver');
    const { formatDueDate } = await import('./dates');
    // 03:00 UTC on the 15th is still the 14th in Vancouver
    expect(formatDueDate('2026-09-15T03:00:00Z')).toMatch(/14/);
  });

  it('returns an empty string for invalid input', async () => {
    const { formatDueDate } = await import('./dates');
    expect(formatDueDate('not-a-date')).toBe('');
  });
});

