'use client';

import { useRouter, useSearchParams } from 'next/navigation';
import type { InvoiceStatus } from '@/lib/types';

const STATUSES: InvoiceStatus[] = ['draft', 'sent', 'paid', 'overdue', 'void'];

function isStatus(value: string | null): value is InvoiceStatus {
  return value !== null && (STATUSES as string[]).includes(value);
}

export function InvoiceFilters() {
  const router = useRouter();
  const params = useSearchParams();
  const raw = params.get('status') ?? undefined;

  function setStatus(next: InvoiceStatus | 'all') {
    const sp = new URLSearchParams(params);
    if (next === 'all') sp.delete('status');
    else sp.set('status', next);
    router.replace(`?${sp.toString()}`);
  }

  return (
    <div className="flex gap-2">
      {(['all', ...STATUSES] as const).map((s) => (
        <button
          key={s}
          type="button"
          onClick={() => setStatus(s)}
          className="rounded-md px-2 py-1 text-sm data-[active=true]:bg-muted"
          data-active={s === (raw ?? 'all')}
        >
          {s}
        </button>
      ))}
      <StatusCount status={raw} />
    </div>
  );
}

