import { GetObjectCommand, PutObjectCommand } from '@aws-sdk/client-s3';
import sharp from 'sharp';
import { s3, BUCKET } from '../s3';
import { logger } from '../logger';

const SIZES = [
  { name: 'thumb', width: 160 },
  { name: 'medium', width: 640 },
  { name: 'large', width: 1600 },
] as const;

export type ProcessImagePayload = { key: string };

export async function processImage({ key }: ProcessImagePayload) {
  const obj = await s3.send(new GetObjectCommand({ Bucket: BUCKET, Key: key }));
  const input = Buffer.from(await obj.Body!.transformToByteArray());

  for (const size of SIZES) {
    const out = await sharp(input)
      .rotate()
      .resize({ width: size.width, withoutEnlargement: true })
      .webp({ quality: 82 })
      .toBuffer();
    await s3.send(
      new PutObjectCommand({
        Bucket: BUCKET,
        Key: `${key.replace(/\.[^.]+$/, '')}/${size.name}.webp`,
        Body: out,
        ContentType: 'image/webp',
      }),
    );
  }
  logger.info({ key, sizes: SIZES.length }, 'image processed');
}

