export interface StatusOptions {
  json?: boolean;
}

export async function status(opts: StatusOptions): Promise<number> {
  const config = await loadConfig();
  const health = await getApiHealth(config.apiUrl);

  const rows: Array<[string, string]> = [
    ['api', health.ok ? pc.green('up') : pc.red('down')],
    ['org', config.orgSlug ?? pc.dim('(not set)')],
    ['queues', 'RabbitMQ  ' + pc.dim(config.workerUrl + ':15672')],
  ];

  if (opts.json) {
    process.stdout.write(JSON.stringify(Object.fromEntries(rows)) + '\n');
    return 0;
  }
  for (const [k, v] of rows) {
    process.stdout.write(pc.bold(k.padEnd(10)) + v + '\n');
  }
  return health.ok ? 0 : 1;
}

